19	method SearchRecursive( a: seq<real>, i: int, j: int, x: real ) returns ( k: int )
20	    decreases j-i;
21	    requires forall p, q :: i <= p < q < j ==> a[p] >= a[q];
22	    ensures i <= k <= j
23	    ensures forall r | i <= r < k :: a[r] >= x;
24	    ensures forall r | k <= r < j :: a[r] < x;
25	
26	{
27	    if i == j
28	    {
29	        return i;
30	    }
31	    var m := i + (j-i)/2;
32	    if a[m] < x
33	    {
34	        k := SearchRecursive(a,i,m,x);
35	    }
36	    else
37	    {
38	        k := SearchRecursive(a,m+1,j,x);
39	    }
40	}
41	
42	method SearchLoop( a: seq<real>, i: int, j: int, x: real ) returns ( k: int )
43	    requires 0 <= i <= j <= |a|;
44	    requires forall p, q :: i <= p < q < j ==> a[p] >= a[q];
45	    ensures i <= k <= j;
46	    ensures forall r | i <= r < k :: a[r] >= x;
47	    ensures forall r | k <= r < j :: a[r] < x;
48	{
49	    if i == j
50	    {
51	        return i;
52	    }
53	    var p := i;
54	    var q := j;
55	    while p != q
56	        decreases q-p;
57	        invariant i <= p <= q <= j;
58	        invariant forall r | i <= r < p :: a[r] >= x;
59	        invariant forall r | q <= r < j :: a[r] < x;
60	    {
61	        var m := p + (q-p)/2;
62	        if a[m] < x
63	        {
64	            q := m;
65	        }
66	        else
67	        {
68	            p := m+1;
69	        }
70	    }
71	    return p;
72	}
73	
74	// Ef eftirfarandi fall er ekki samþykkt þá eru
75	// föllin ekki að haga sér rétt að mati Dafny.
76	method Test( a: seq<real>, x: real )
77	    requires forall p,q | 0 <= p < q < |a| :: a[p] >= a[q];
78	{
79	
80	    var k1 := SearchLoop(a,0,|a|,x);
81	    assert forall r | 0 <= r < k1 :: a[r] >= x;
82	    assert forall r | k1 <= r < |a| :: a[r] < x;
83	    var k2 := SearchRecursive(a,0,|a|,x);
84	    assert forall r | 0 <= r < k2 :: a[r] >= x;
85	    assert forall r | k2 <= r < |a| :: a[r] < x;
86	}

